python3 - <<'EOF'
import re, glob
from collections import defaultdict

sev_re = re.compile(r'\[(ERROR|WARNING|INFO|DEBUG)\]')
periods = {
    'today':       ('2025-08-12', '2025-08-12'),
    'last_7_days': ('2025-08-06', '2025-08-12'),
    'last_30_days':('2025-07-14', '2025-08-12'),
    'month_to_date': ('2025-08-01', '2025-08-12'),
    'total':       (None, None),
}
counts = {p: defaultdict(int) for p in periods}

for f in sorted(glob.glob('/app/logs/*.log')):
    for line in open(f):
        line = line.strip()
        m = sev_re.search(line)
        if not m: continue
        v = m.group(1)
        if v not in ('ERROR','WARNING','INFO'): continue
        d = line[0:10]
        for p,(lo,hi) in periods.items():
            if p=='total':
                counts[p][v]+=1
            elif lo <= d <= hi:
                counts[p][v]+=1

with open('/app/summary.csv','w') as out:
    out.write("period,severity,count\n")
    for p in ['today','last_7_days','last_30_days','month_to_date','total']:
        for v in ['ERROR','WARNING','INFO']:
            out.write(f"{p},{v},{counts[p][v]}\n")

for p in ['today','last_7_days','last_30_days','month_to_date','total']:
    print(p, dict(counts[p]))
EOF
